for(plane,rows)in rows.iter().enumerate(){for(mesh,group)in rows{if let Some(group)=group.as_ref().filter(|_|records.is_some_and(|records|records.bind_record(&mut pass,mesh))){pass.set_pipeline(shared);pass.set_bind_group(3,group,&[]);pass.draw(0..mesh.geometry.index_count,0..1);}else{pass.set_pipeline(pipeline);pass.set_bind_group(3,self.record_group.as_ref().unwrap(),&[]);mesh.bind_model(&mut pass);mesh.geometry.draw_range(&mut pass,plane as u32..plane as u32+1);}}}